import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line != null && !line.isEmpty()) { StringTokenizer st = new StringTokenizer(line); if (st.hasMoreTokens()) { int n = Integer.parseInt(st.nextToken()); System.out.println(n); } } } }